  FT["PH-H2818"] = {"id":"PH-H2818","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3341_1961.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第487号联邦法（即《授予哥打巴托电灯电力公司在哥打巴托市经营电灯、热力与电力系统特许权》）的法案","en":"An Act Amending Commonwealth Act Numbered Four Hundred and Eighty-Seven, Entitled “An Act to Grant to Cotabato Light and Power Company, Incorporated, a Franchise for an Electric Light, Heat, and Power System in Cotabato, Cotabato”","orig":"An Act Amending Commonwealth Act Numbered Four Hundred and Eighty-Seven, Entitled “An Act to Grant to Cotabato Light and Power Company, Incorporated, a Franchise for an Electric Light, Heat, and Power System in Cotabato, Cotabato”","vi":"Đạo luật sửa đổi Đạo luật Thịnh vượng chung số 487","th":"พระราชบัญญัติแก้ไขเพิ่มเติมพระราชบัญญัติเครือรัฐที่ 487","id":"Undang-Undang mengubah Undang-Undang Persemakmuran No. 487","ms":"Akta meminda Akta Komanwel No. 487"},"level":"law","status":"active","topics":["investment","company"],"docNumber":"Republic Act No. 3341","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3341_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2818-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Commonwealth Act Numbered Four hundred and eighty-seven is hereby amended to read as follows:\n\"Sec. 1. Subject to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, and to the provisions of the Constitution, there is granted to the Cotabato Light and Power Company, Incorporated, for a period of twenty-five years from the approval of this Act, the right, privileges and authority to construct, maintain and operate an electric light, heat, and power plant for the purpose of generating and distributing electric light, heat or power for sale within the limits of the City of Cotabato and the municipalities of Nulling and Dinaig, Province of Cotabato.\""}},{"id":"PH-H2818-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1961."}}],"pack":"ph-p40","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Commonwealth Act Numbered Four Hundred and Eighty-Seven, Entitled “An Act to Grant to Cotabato Light and Power Company, Incorporated, a Franchise for an Electric Light, Heat, and Power System in Cotabato, Cotabato”","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2819"] = {"id":"PH-H2819","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3342_1961.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"为安蒂克省设立一名助理省检察官职位，为此重新制定《行政法典》第1674条第一段第26项（经修正）的法案","en":"An Act Creating the Position of One Assistant Provincial Fiscal for the Province of Antique, Reenacting for the Purpose the Twenty-Sixth Subparagraph of the First Paragraph of Section Sixteen Hundred and Seventy-Four of the Administrative Code, as Amended","orig":"An Act Creating the Position of One Assistant Provincial Fiscal for the Province of Antique, Reenacting for the Purpose the Twenty-Sixth Subparagraph of the First Paragraph of Section Sixteen Hundred and Seventy-Four of the Administrative Code, as Amended"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 3342","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3342_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2819-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The provision of Section sixteen hundred seventy-four of the Administrative Code, as amended, relative to the number of assistant provincial fiscals in the Province of Cagayan, is further amended to read as follows:\n\"Cagayan, five assistant provincial fiscals;\""}},{"id":"PH-H2819-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1961."}}],"pack":"ph-p40","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Position of One Assistant Provincial Fiscal for the Province of Antique, Reenacting for the Purpose the Twenty-Sixth Subparagraph of the First Paragraph of Section Sixteen Hundred and Seventy-Four of the Administrative Code, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2820"] = {"id":"PH-H2820","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3343_1961.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"授予 Valentin O. Pacina 在宿务省 Bantayan 岛 Bantayan 市镇建设、维护和运营制冰厂与冷藏库并在该岛销售冰和供应冷藏的特许权法案","en":"An Act Granting Valentin O. Pacina a Franchise to Construct, Maintain and Operate an Ice Plant and Cold Storage in the Municipality of Bantayan, Island of Bantayan, Province of Cebu, and to Sell Ice and Supply Cold Storage in Said Island","orig":"An Act Granting Valentin O. Pacina a Franchise to Construct, Maintain and Operate an Ice Plant and Cold Storage in the Municipality of Bantayan, Island of Bantayan, Province of Cebu, and to Sell Ice and Supply Cold Storage in Said Island","vi":"Đạo luật cấp đặc quyền cho Valentin O. Pacina để xây dựng, duy trì và vận hành nhà máy nước đá và kho lạnh tại Thị trấn Bantayan, Đảo Bantayan, Tỉnh Cebu, và bán nước đá và cung cấp dịch vụ kho lạnh","th":"พระราชบัญญัติให้สัมปทานแก่ Valentin O. Pacina ในการก่อสร้าง บำรุงรักษา และดำเนินการโรงงานน้ำแข็งและห้องเย็นในเทศบาล Bantayan เกาะ Bantayan จังหวัด Cebu และจำหน่ายน้ำแข็งและให้บริการห้องเย็น","id":"Undang-Undang memberikan konsesi kepada Valentin O. Pacina untuk membangun, memelihara, dan mengoperasikan pabrik es dan penyimpanan dingin di Kotamadya Bantayan, Pulau Bantayan, Provinsi Cebu, dan menjual es serta menyediakan layanan penyimpanan dingin","ms":"Akta memberikan konsesi kepada Valentin O. Pacina untuk membina, menyelenggarakan dan mengendalikan kilang ais dan stor sejuk di Perbandaran Bantayan, Pulau Bantayan, Wilayah Cebu, dan menjual ais serta menyediakan perkhidmatan stor sejuk"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 3343","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-18","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3343_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2820-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in this Act and in Commonwealth Act Numbered one hundred forty-six, as amended, and to the provisions of the Constitution, there is granted to Valentin O. Pacina, for a period of fifty-years from the approval of this Act, the right, privilege and authority to construct, maintain and operate an ice plant and cold storage in the Municipality of Bantayan, Island of Bantayan, Province of Cebu, for the purpose of manufacturing ice for distribution and sale, and for supplying cold storage, in the said island."}},{"id":"PH-H2820-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The grantee shall manufacture and supply ice up to the limit of the capacity of his plant, said limit to be determined by the Public Service Commission, and sell the same at rates to be determined by the said Commission."}},{"id":"PH-H2820-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All the apparatus and appurtenances to be used by the grantee shall be modern, safe and first class in every respect, and the grantee shall, whenever the Public Service Commission shall determine that public interest reasonably requires it, change or alter any of its apparatus and appurtenances at grantee’s expense."}},{"id":"PH-H2820-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"If the grantee shall not commence the manufacture of ice for distribution and sale within the Island of Bantayan, Province of Cebu, within two years from the approval of this Act, unless prevented by an act of God or force majeure, martial law, riot, civil commotion, usurpation by a military power or any other cause beyond the grantee’s control, this franchise shall become null and void."}},{"id":"PH-H2820-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This franchise is granted with the understanding and upon the condition that it shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires."}},{"id":"PH-H2820-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The books, records and accounts of the grantee shall always be open to the inspection of the Auditor General or his authorized representatives, and it shall be the duty of the grantee to submit to the Auditor General quarterly reports in duplicate showing the gross receipts for the quarter past."}},{"id":"PH-H2820-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"In the event of any competing person, natural or juridical, receiving from the Congress of the Philippines a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of such competing person."}},{"id":"PH-H2820-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1961."}}],"pack":"ph-p40","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Valentin O. Pacina a Franchise to Construct, Maintain and Operate an Ice Plant and Cold Storage in the Municipality of Bantayan, Island of Bantayan, Province of Cebu, and to Sell Ice and Supply Cold Storage in Said Island","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
