  FT["PH-H2838"] = {"id":"PH-H2838","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3361_1961.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将奎松省蒂亚翁市镇的马蒂蓬索村划归同省圣安东尼奥市镇的法案","en":"An Act Making the Barrio of Matipunso of the Municipality of Tiaong, Province of Quezon, a Part of the Municipality of San Antonio, Same Province","orig":"An Act Making the Barrio of Matipunso of the Municipality of Tiaong, Province of Quezon, a Part of the Municipality of San Antonio, Same Province"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3361","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3361_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2838-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The barrio of Matipunso is hereby separated from the Municipality of Tiaong, Province of Quezon, and is consolidated with and made a part of the Municipality of San Antonio, same province."}},{"id":"PH-H2838-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1961."}}],"pack":"ph-p40","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Making the Barrio of Matipunso of the Municipality of Tiaong, Province of Quezon, a Part of the Municipality of San Antonio, Same Province","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
